"""Verify saved bounded excerpts against exact executable; attach findings."""
import argparse,hashlib,json,struct,sys
from pathlib import Path
REPO=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(REPO/'tools'))
ap=argparse.ArgumentParser();ap.add_argument('--archive',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);args=ap.parse_args();HERE=args.output
from analyze_vic3 import PE,read_input
from runtime_function_groups import backed_bytes
archive=args.archive;binary,member=read_input(archive,'victoria3.exe');pe=PE(binary)
expected='9b6f133a5dc235de9135d7b57e86ceda8282d1ba6c0e185f3ee19c22f8917f54'
assert hashlib.sha256(binary).hexdigest()==expected
files=['first-pass','economics-inner','shared-helpers','employment-buffer-init','allocator-continuations']
nodes={};relative_edges=0
for name in files:
    doc=json.loads((HERE/(name+'.json')).read_text('utf8'))
    assert doc['executable_sha256']==expected
    for node in doc['selected_groups']:
        assert node['fully_decoded'];nodes[node['entry_rva']]=node
        by={int(i['rva'],16):i for i in node['instructions']}
        for r in node['ranges']:
            lo,hi=int(r['begin_rva'],16),int(r['end_rva'],16)
            rows=[i for i in node['instructions'] if lo<=int(i['rva'],16)<hi]
            joined=b''.join(bytes.fromhex(i['bytes']) for i in rows)
            assert len(joined)==hi-lo and joined==backed_bytes(binary,pe,lo,hi-lo)
            assert hashlib.sha256(joined).hexdigest()==r['sha256']
        for edge in node['direct_edges']:
            ins=by[int(edge['instruction_rva'],16)];raw=bytes.fromhex(ins['bytes'])
            if raw[0] in (0xe8,0xe9) and len(raw)==5:
                target=int(ins['rva'],16)+5+struct.unpack('<i',raw[1:])[0]
                assert target==int(edge['target_rva'],16);relative_edges+=1
