out={'format_version':1,'date':'2026-10-05','archive':str(archive),'archive_size_bytes':archive.stat().st_size,'archive_sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'executable_member':member,'executable_size_bytes':len(binary),'executable_sha256':expected,'repository_base':'2bde7dc','verification':{'groups':len(nodes),'total_decoded_bytes':sum(n['decoded_bytes'] for n in nodes.values()),'all_ranges_equal_saved_instruction_bytes':True,'independently_checked_e8_e9_edges':relative_edges},'findings':findings,'scope_limit':'Selected unwind groups only; no runtime execution, injection, binary patch, installed-game writes, performance causality or improvement proven.'}
